const PASTA_ENTRIES = PASTA_ITEMS.flatMap(d => d.ex.map(x => ({ ...x, distilleryId:d.id, distillery:d.name, region:d.region, lat:d.lat, lon:d.lon })));
const PASTA_REGIONS = {"piemonte": {"jp": "ピエモンテ", "en": "PIEMONTE", "area": "north", "label": [7.9, 45.0], "desc": "アルプスのふもとの北イタリア。卵黄をたっぷり使う細い手打ち麺タヤリンや、ひと口サイズの詰め物パスタが名物。秋のアルバの白トリュフでも知られる。", "pick": "北イタリア", "areaJp": "北イタリア"}, "lombardia": {"jp": "ロンバルディア", "en": "LOMBARDIA", "area": "north", "label": [9.9, 45.75], "desc": "ミラノのある北イタリアの州。米やバターの文化が強く、パスタは詰め物や、そば粉の麺など山の郷土料理が中心。", "pick": "北イタリア", "areaJp": "北イタリア"}, "veneto": {"jp": "ヴェネト", "en": "VENETO", "area": "north", "label": [12.0, 45.65], "desc": "ヴェネツィアのある北東部の州。押し出し機で作る太い麺ビゴリや、じゃがいものニョッキが親しまれる。", "pick": "北イタリア", "areaJp": "北イタリア"}, "liguria": {"jp": "リグーリア", "en": "LIGURIA", "area": "north", "label": [8.6, 44.25], "desc": "ジェノヴァを中心とする地中海沿いの細長い州。バジルのペースト「ペスト」の故郷で、ねじれたトロフィエや、くるみのソースで食べる詰め物パスタがある。", "pick": "北イタリア", "areaJp": "北イタリア"}, "emilia": {"jp": "エミリア・ロマーニャ", "en": "EMILIA-ROMAGNA", "area": "north", "label": [11.2, 44.55], "desc": "ボローニャやモデナ、パルマのある「食の都」。卵入りの手打ちパスタの本場で、タリアテッレ、トルテッリーニ、ラザーニャなどを生んだ。パルミジャーノ・レッジャーノや生ハムの産地でもある。", "pick": "北イタリア", "areaJp": "北イタリア"}, "toscana": {"jp": "トスカーナ", "en": "TOSCANA", "area": "center", "label": [11.1, 43.35], "desc": "フィレンツェやシエナのある中部の州。イノシシや野うさぎなど山の幸のラグーと、幅広のパッパルデッレ、手でのばす太麺ピチが名物。", "pick": "中部イタリア", "areaJp": "中部イタリア"}, "lazio": {"jp": "ラツィオ（ローマ）", "en": "LAZIO", "short": "ローマ", "area": "center", "label": [12.6, 41.95], "desc": "首都ローマのある州。カルボナーラ、アマトリチャーナ、カチョ・エ・ペペ、グリーチャの「ローマの4大パスタ」は、どれも豚ほほ肉の塩漬けグアンチャーレや羊乳チーズのペコリーノ・ロマーノを使う。", "pick": "中部イタリア", "areaJp": "中部イタリア"}, "abruzzo": {"jp": "アブルッツォ・モリーゼ", "en": "ABRUZZO & MOLISE", "short": "アブルッツォ", "area": "south", "label": [14.1, 42.15], "desc": "アドリア海とアペニン山脈にはさまれた、羊飼いの文化が残る土地。弦を張った道具で切るキタッラや、指で転がすカヴァテッリが伝わる。乾麺の大手メーカーも多い。", "pick": "南イタリア", "areaJp": "南イタリア"}, "campania": {"jp": "カンパニア（ナポリ）", "en": "CAMPANIA", "short": "ナポリ", "area": "south", "label": [14.6, 40.85], "desc": "ナポリのある南イタリアの州。近郊のグラニャーノは乾麺の町として知られ、トマトソースとパスタの組み合わせもここで広まった。魚介のパスタや、肉を長時間煮込むラグーも名物。", "pick": "南イタリア", "areaJp": "南イタリア"}, "puglia": {"jp": "プーリア", "en": "PUGLIA", "area": "south", "label": [16.4, 41.0], "desc": "イタリア半島の「かかと」にあたる州。デュラム小麦とオリーブの一大産地で、小さな耳の形のオレッキエッテを、ほろ苦い青菜と合わせる。", "pick": "南イタリア", "areaJp": "南イタリア"}, "sicilia": {"jp": "シチリア", "en": "SICILIA", "area": "islands", "label": [14.2, 37.55], "desc": "地中海最大の島。アラブやスペインの影響を受け、いわしとウイキョウ、レーズン、松の実、アーモンドなどを使った独特のソースが多い。", "pick": "シチリア・サルデーニャ", "areaJp": "シチリア・サルデーニャ"}, "sardegna": {"jp": "サルデーニャ", "en": "SARDEGNA", "area": "islands", "label": [9.0, 40.05], "desc": "イタリア西方の大きな島。サフランを練り込んだ小さなマッロレッドゥス、粒状のフレーグラ、麦の穂の形の詰め物クルルジョネスなど、島ならではのパスタがある。", "pick": "シチリア・サルデーニャ", "areaJp": "シチリア・サルデーニャ"}};
const PASTA_COUNTRIES = {"italy": {"jp": "イタリア", "style": "イタリア", "en": "ITALY", "mark": [12.5, 42.8], "map": "italy", "regions": ["piemonte", "lombardia", "veneto", "liguria", "emilia", "toscana", "lazio", "abruzzo", "campania", "puglia", "sicilia", "sardegna"], "desc": "パスタの国。北部は小麦粉と卵で作る手打ちの生パスタやバター、南部はデュラム小麦と水で作る乾麺やオリーブオイルとトマトが中心と、地域によって文化が大きく違う。地図の州をタップすると、その土地のパスタを見られる。"}};
const PASTA_TYPES = [{"id": "long", "name": "ロングパスタ", "en": "Long Pasta", "kind": "長い", "p": [4, 2, 4, 0, 3, 2, 2, 3], "tags": ["乾麺", "デュラム小麦", "アルデンテ"], "home": "イタリア全土（特に南部）", "desc": "スパゲッティのような細長いパスタ。南イタリアではデュラム小麦のセモリナ粉と水だけで作った乾麺が中心で、オイルやトマトのさらりとしたソースとよく合う。", "dough": "durum"}, {"id": "ribbon", "name": "卵の平打ち麺", "en": "Egg Ribbon Pasta", "kind": "長い", "p": [2, 4, 3, 5, 4, 3, 3, 2], "tags": ["卵", "手打ち", "生パスタ"], "home": "北イタリア、中部イタリア", "desc": "小麦粉と卵を練った生地を薄くのばし、帯状に切った手打ち麺。表面の細かなざらつきと卵のコクが、肉のラグーやバター、クリームのソースをよく受け止める。", "dough": "egg"}, {"id": "short", "name": "ショートパスタ", "en": "Short Pasta", "kind": "短い", "p": [5, 3, 4, 0, 4, 4, 3, 2], "tags": ["乾麺", "筒形", "煮込みソース"], "home": "イタリア全土", "desc": "筒やらせんなど、短く切ったパスタ。穴や溝にソースが入り込み、ごろっとした具や濃いソースとからみやすい。", "dough": "durum"}, {"id": "handmade", "name": "郷土の手作りパスタ", "en": "Regional Handmade Pasta", "kind": "短い", "p": [4, 4, 4, 0, 4, 3, 4, 2], "tags": ["手作り", "デュラム小麦", "郷土料理"], "home": "南イタリア、リグーリア、サルデーニャ", "desc": "指や手のひら、細い棒を使って、ひとつずつ形づくる小さなパスタ。地方ごとに独自の形があり、その土地の野菜や肉のソースと合わせて受け継がれてきた。", "dough": "durum"}, {"id": "filled", "name": "詰め物パスタ", "en": "Filled Pasta", "kind": "包む", "p": [2, 4, 3, 4, 2, 3, 1, 2], "tags": ["詰め物", "卵", "手作り"], "home": "北イタリア、サルデーニャ", "desc": "薄い生地で肉やチーズ、野菜を包んだパスタ。詰め物が主役なので、バターやスープなど味を邪魔しないシンプルなソースで食べることが多い。", "dough": "egg"}, {"id": "gnocchi", "name": "ニョッキ", "en": "Gnocchi", "kind": "その他", "p": [1, 5, 2, 1, 3, 3, 2, 2], "tags": ["団子", "じゃがいも", "もちもち"], "home": "北イタリア、ローマ", "desc": "じゃがいもやセモリナ粉などで作る団子状のパスタ。ふんわり、もっちりとした食感。", "dough": "potato"}, {"id": "baked", "name": "シート・オーブン焼き", "en": "Baked Pasta", "kind": "その他", "p": [2, 3, 3, 3, 5, 4, 1, 1], "tags": ["オーブン", "重ねる", "ごちそう"], "home": "エミリア・ロマーニャ、南イタリア、シチリア", "desc": "板状のパスタや小さなパスタを、ソースやチーズと重ねてオーブンで焼く料理用のパスタ。祝日や日曜日のごちそうとして作られてきた。", "dough": "green"}, {"id": "small", "name": "スープ用の小さなパスタ", "en": "Small Pasta for Soup", "kind": "その他", "p": [3, 3, 4, 0, 2, 1, 2, 4], "tags": ["スープ", "豆", "小粒"], "home": "イタリア全土", "desc": "豆や野菜と一緒に煮込んだり、スープに浮かべたりする小さなパスタ。スプーンで食べる家庭料理に欠かせない。", "dough": "toast"}];
const PASTA_SAUCES = {"ragu_bolognese": {"name": "ラグー・アッラ・ボロニェーゼ", "en": "Ragù alla Bolognese", "origin": "ボローニャ（エミリア・ロマーニャ）", "color": "#7A4A2A", "ings": ["牛ひき肉", "パンチェッタ", "玉ねぎ・にんじん・セロリ", "トマト", "白ワイン", "牛乳"], "desc": "香味野菜と肉を、ワインと牛乳、少しのトマトで何時間も煮込む肉のソース。1982年にボローニャ商工会議所にレシピが登録された。日本の「ミートソース」の元になった。", "kind": "肉の煮込み（ラグー）", "tip": "肉は大きめの鍋で、水分がなくなるまでしっかり焼きつける。牛乳を加えると肉がやわらかくなり、まろやかに仕上がる。弱火で2〜3時間煮込むのが本場流。"}, "pesto": {"name": "ペスト・ジェノヴェーゼ", "en": "Pesto alla Genovese", "origin": "ジェノヴァ（リグーリア）", "color": "#5E8C3A", "ings": ["バジル", "松の実", "にんにく", "パルミジャーノ", "ペコリーノ", "オリーブオイル"], "desc": "バジルを大理石のすり鉢ですりつぶして作る、火を通さない緑のソース。ジェノヴァでは、パスタと一緒にじゃがいもといんげんをゆでて和えることも多い。", "kind": "ペースト", "tip": "バジルは加熱せず、熱いパスタにそのまま和える。ミキサーを使うときは、刃や材料を冷やしておくと色が黒くなりにくい。ゆで汁で少しのばすとからみやすい。"}, "carbonara": {"name": "カルボナーラ", "en": "Carbonara", "origin": "ローマ（ラツィオ）", "color": "#E9B53A", "ings": ["グアンチャーレ（豚ほほ肉の塩漬け）", "卵黄", "ペコリーノ・ロマーノ", "黒こしょう"], "desc": "グアンチャーレの脂に、卵とペコリーノを合わせてとろりと仕上げる。本場では生クリームを使わない。20世紀半ばに広まった、比較的新しい料理。", "recipe": "r-carbonara", "kind": "チーズ・卵・クリームのソース", "tip": "卵黄とすりおろしたペコリーノをよく混ぜておき、火を止めたフライパンでパスタと和える。火にかけたままだと卵が固まってしまう。ゆで汁で濃度を調整する。"}, "cacio_pepe": {"name": "カチョ・エ・ペペ", "en": "Cacio e Pepe", "origin": "ローマ（ラツィオ）", "color": "#F1E6CF", "ings": ["ペコリーノ・ロマーノ", "黒こしょう", "ゆで汁"], "desc": "材料はチーズとこしょうだけ。ゆで汁でペコリーノを溶かし、ダマにせずクリーム状にまとめるのが腕の見せどころ。", "kind": "チーズ・卵・クリームのソース", "tip": "ペコリーノは細かくすりおろし、少し冷ましたゆで汁で溶いてペースト状にしてから、パスタと手早く混ぜる。熱すぎるとチーズがダマになる。"}, "gricia": {"name": "グリーチャ", "en": "Gricia", "origin": "ラツィオ", "color": "#F1E6CF", "ings": ["グアンチャーレ", "ペコリーノ・ロマーノ", "黒こしょう"], "desc": "グアンチャーレとペコリーノで作る、トマトを使わない「白いアマトリチャーナ」。トマトがヨーロッパに広まる前からある、アマトリチャーナの原型ともいわれる。", "kind": "チーズ・卵・クリームのソース", "tip": "グアンチャーレから出た脂と、ゆで汁、ペコリーノを混ぜてクリーム状にする。黒こしょうはたっぷり。"}, "amatriciana": {"name": "アマトリチャーナ", "en": "Amatriciana", "origin": "アマトリーチェ（ラツィオ）", "color": "#C2412D", "ings": ["グアンチャーレ", "トマト", "ペコリーノ・ロマーノ", "白ワイン", "唐辛子"], "desc": "ラツィオ州の山あいの町アマトリーチェ生まれ。グアンチャーレの脂の旨みと、トマトの酸味、ペコリーノの塩気が重なる。", "kind": "トマトのソース", "tip": "グアンチャーレを弱火でじっくり炒めて脂を出し、カリッとさせてから白ワインとトマトを加える。グアンチャーレがなければパンチェッタで代用できる。"}, "arrabbiata": {"name": "アラビアータ", "en": "Arrabbiata", "origin": "ローマ（ラツィオ）", "color": "#C2412D", "ings": ["トマト", "にんにく", "唐辛子", "オリーブオイル", "イタリアンパセリ"], "desc": "「怒った」という意味の、唐辛子をきかせた辛いトマトソース。食べると怒ったように顔が赤くなるから、ともいわれる。", "kind": "トマトのソース", "tip": "唐辛子は弱火のオイルでじっくり香りと辛みを移す。辛さは唐辛子の量と、加熱する時間で調整できる。"}, "pomodoro": {"name": "ポモドーロ（トマトとバジル）", "en": "Pomodoro e Basilico", "origin": "ナポリ（カンパニア）", "color": "#C2412D", "ings": ["トマト", "にんにく", "バジル", "オリーブオイル"], "desc": "トマトとバジルだけのシンプルなソース。パスタにトマトソースを合わせる食べ方は、18〜19世紀のナポリで広まった。", "kind": "トマトのソース", "tip": "トマトはホール缶なら手でつぶし、オリーブオイルでにんにくを香らせてから15〜20分ほど煮詰める。バジルは火を止める直前か、盛りつけてからちぎってのせると香りが飛ばない。"}, "puttanesca": {"name": "プッタネスカ", "en": "Puttanesca", "origin": "ナポリ（カンパニア）", "color": "#C2412D", "ings": ["トマト", "黒オリーブ", "ケッパー", "アンチョビ", "にんにく", "唐辛子"], "desc": "戸棚にある保存食で手早く作れる、塩気と香りの強いトマトソース。名前の由来には諸説ある。", "kind": "トマトのソース", "tip": "アンチョビはオイルで溶かすように炒める。オリーブとケッパーは塩気が強いので、パスタのゆで湯の塩は控えめに。"}, "vongole": {"name": "ボンゴレ・ビアンコ", "en": "Vongole in Bianco", "origin": "ナポリ（カンパニア）", "color": "#F1E6CF", "ings": ["あさり", "にんにく", "白ワイン", "イタリアンパセリ", "オリーブオイル"], "desc": "あさりの蒸し汁をパスタに吸わせる、トマトを使わない「白い」ボンゴレ。ナポリのクリスマス・イブの定番でもある。", "kind": "魚介のソース", "tip": "あさりは砂抜きしておき、にんにくのオイルに入れて白ワインでふたをして蒸す。口が開いたらいったん取り出し、硬くなるのを防ぐ。蒸し汁にパスタを入れて吸わせる。"}, "aglio_olio": {"name": "アーリオ・オーリオ・エ・ペペロンチーノ", "en": "Aglio, Olio e Peperoncino", "origin": "南イタリア", "color": "#E2C15A", "ings": ["にんにく", "オリーブオイル", "唐辛子", "イタリアンパセリ"], "desc": "にんにくと唐辛子の香りをオリーブオイルに移すだけの、いちばんシンプルなパスタ。ゆで汁を加えてオイルを乳化させるのがおいしく作るコツ。", "recipe": "r-peperoncino", "kind": "オイルのソース", "tip": "冷たいオイルににんにくを入れてから弱火にかけ、きつね色になる手前で唐辛子を加える。ゆで汁を少し加えてフライパンをゆすり、白くとろりとしたら乳化した合図。"}, "ragu_napoletano": {"name": "ナポリ風ラグー", "en": "Ragù Napoletano", "origin": "ナポリ（カンパニア）", "color": "#C2412D", "ings": ["牛・豚のかたまり肉", "トマト", "赤ワイン", "玉ねぎ"], "desc": "かたまり肉をトマトで何時間も煮込む、日曜日のごちそう。ソースはパスタに、やわらかくなった肉はメイン料理として別に食べる。", "kind": "肉の煮込み（ラグー）", "tip": "肉のかたまりに焼き色をつけてから、トマトと赤ワインでごく弱火で4〜6時間煮込む。ナポリでは「ラグーはぽこぽこと、ささやくように煮る」といわれる。"}, "genovese": {"name": "ジェノヴェーゼ（ナポリ風）", "en": "Genovese Napoletana", "origin": "ナポリ（カンパニア）", "color": "#7A4A2A", "ings": ["玉ねぎ（たっぷり）", "牛肉", "白ワイン", "にんじん・セロリ"], "desc": "名前はジェノヴァでも、ナポリの料理。大量の玉ねぎを牛肉と一緒にとろとろになるまで煮込む、甘くて茶色いソース。バジルのペーストとは別物。", "kind": "肉の煮込み（ラグー）", "tip": "玉ねぎは肉と同じくらいの重さ、またはそれ以上使い、ふたをして弱火で3時間ほど、茶色くとろとろになるまで煮る。"}, "frutti_di_mare": {"name": "フルッティ・ディ・マーレ（魚介）", "en": "Frutti di Mare", "origin": "カンパニアなど南イタリアの海沿い", "color": "#D98A5A", "ings": ["ムール貝", "あさり", "エビ", "イカ", "ミニトマト", "にんにく"], "desc": "貝やエビ、イカの旨みが詰まったソース。貝の口が開いたらすぐにパスタと合わせ、魚介を煮すぎないのがコツ。", "kind": "魚介のソース", "tip": "火の通りにくいものから順に加え、貝の口が開いたらすぐにパスタと合わせる。魚介は煮すぎると硬くなる。"}, "nero_di_seppia": {"name": "イカ墨", "en": "Nero di Seppia", "origin": "ヴェネツィア、シチリア", "color": "#2A2A2A", "ings": ["イカ", "イカ墨", "にんにく", "白ワイン", "トマト"], "desc": "真っ黒な見た目に、イカの甘みと海の旨みが詰まったソース。ヴェネツィアとシチリアで特に好まれる。", "kind": "魚介のソース", "tip": "イカは煮すぎないように。イカ墨は少量でも色が濃く出るので、市販のペーストを使うと手軽。"}, "fagioli": {"name": "パスタ・エ・ファジョーリ（豆の煮込み）", "en": "Pasta e Fagioli", "origin": "ナポリなど各地", "color": "#7A4A2A", "ings": ["いんげん豆", "トマト", "セロリ", "にんにく", "オリーブオイル"], "desc": "パスタを豆と一緒に煮込む、スープとリゾットの中間のような家庭料理。豆の一部をつぶして、とろみをつける。", "kind": "スープ・豆と煮込む", "tip": "豆の一部をつぶしてとろみをつけ、パスタは豆のスープで直接煮る。オリーブオイルを仕上げにひと回しかける。"}, "ceci": {"name": "チチェリ・エ・トリア（ひよこ豆）", "en": "Ciceri e Tria", "origin": "サレント（プーリア）", "color": "#E6C98E", "ings": ["ひよこ豆", "玉ねぎ", "にんにく", "ローリエ", "オリーブオイル"], "desc": "ひよこ豆と一緒に煮込んだパスタに、油で揚げてカリッとさせた同じパスタをのせる。やわらかさと香ばしさの対比が楽しい、アラブ由来ともいわれる料理。", "kind": "スープ・豆と煮込む", "tip": "パスタの一部を油で揚げてカリッとさせ、残りはひよこ豆と一緒に煮る。食べる直前に揚げたパスタをのせる。"}, "cime_di_rapa": {"name": "チーメ・ディ・ラーパ（青菜）", "en": "Cime di Rapa", "origin": "プーリア", "color": "#5E8C3A", "ings": ["チーメ・ディ・ラーパ（かぶの仲間の若い茎と葉）", "にんにく", "アンチョビ", "唐辛子", "オリーブオイル"], "desc": "ほろ苦い青菜をパスタと同じ鍋でゆで、にんにくとアンチョビのオイルで和える。日本では菜の花で代用できる。", "kind": "オイルのソース", "tip": "青菜はパスタと同じ鍋で、ゆで上がりの数分前に入れる。ほろ苦さとアンチョビの塩気がよく合う。"}, "norma": {"name": "ノルマ風（なすとトマト）", "en": "alla Norma", "origin": "カターニア（シチリア）", "color": "#C2412D", "ings": ["揚げなす", "トマト", "バジル", "リコッタ・サラータ（塩漬けのリコッタ）"], "desc": "カターニア出身の作曲家ベッリーニのオペラ『ノルマ』にちなむといわれる名。揚げなすとトマトに、かための塩漬けリコッタをすりおろして。", "kind": "トマトのソース", "tip": "なすは多めの油で揚げるか揚げ焼きにし、仕上げにのせる。リコッタ・サラータがなければ、ペコリーノやパルミジャーノで代用を。"}, "sarde": {"name": "パスタ・コン・レ・サルデ（いわしとウイキョウ）", "en": "Pasta con le Sarde", "origin": "パレルモ（シチリア）", "color": "#E9B53A", "ings": ["いわし", "野生のウイキョウ（フェンネル）", "松の実", "レーズン", "サフラン", "炒ったパン粉"], "desc": "アラブ文化の影響を受けた、甘さと塩気が交じり合うパレルモの名物。チーズの代わりに、炒ったパン粉をかける。", "kind": "魚介のソース", "tip": "いわしは開いて一部をソースに崩し入れる。レーズンはぬるま湯で戻し、パン粉はオリーブオイルできつね色に炒っておく。"}, "pesto_trapanese": {"name": "ペスト・トラパネーゼ", "en": "Pesto alla Trapanese", "origin": "トラーパニ（シチリア）", "color": "#C2412D", "ings": ["トマト", "アーモンド", "バジル", "にんにく", "ペコリーノ"], "desc": "ジェノヴァの船乗りが伝えたペーストが、シチリアでトマトとアーモンドの赤いペーストになったといわれる。火を使わずに作る。", "kind": "ペースト", "tip": "アーモンドは軽く炒ってから砕く。トマトは湯むきして種を除き、すべての材料を一緒にすりつぶす。火は使わない。"}, "anelletti_forno": {"name": "パレルモ風オーブン焼き", "en": "Anelletti al Forno", "origin": "パレルモ（シチリア）", "color": "#C2412D", "ings": ["肉のラグー", "グリーンピース", "揚げなす", "カチョカヴァッロ（チーズ）", "パン粉"], "desc": "パスタとラグー、なす、チーズを型に詰めてオーブンで焼き、ケーキのように切り分ける。パレルモの日曜日のごちそう。", "kind": "肉の煮込み（ラグー）", "tip": "パスタは少しかためにゆで、ラグーと具材を混ぜて型に詰める。パン粉をふって焼き、少し冷ましてから型から出すときれいに切り分けられる。"}, "campidanese": {"name": "カンピダーノ風", "en": "alla Campidanese", "origin": "サルデーニャ", "color": "#C2412D", "ings": ["サルシッチャ（生ソーセージ）", "トマト", "サフラン", "ペコリーノ・サルド"], "desc": "フェンネルの香るサルデーニャのソーセージをトマトで煮込み、島の特産のサフランで香りづけする。", "kind": "トマトのソース", "tip": "サルシッチャは皮を外して中身をほぐして炒める。サフランは少量のぬるま湯に浸して色と香りを出してから加える。"}, "burro_salvia": {"name": "バターとセージ", "en": "Burro e Salvia", "origin": "北イタリア", "color": "#E9B53A", "ings": ["バター", "セージ", "パルミジャーノ"], "desc": "バターでセージの葉を香りが立つまで温めるだけ。詰め物パスタやニョッキの味を引き立てる、北イタリアの定番。", "kind": "バターのソース", "tip": "バターを中火で溶かし、泡が落ち着いてセージがカリッとしたらすぐに火から下ろす。ゆで汁を少し加えると、パスタによくからむ。"}, "burro_parmigiano": {"name": "バターとパルミジャーノ", "en": "Burro e Parmigiano", "origin": "ローマ、北イタリア", "color": "#F1E6CF", "ings": ["バター", "パルミジャーノ・レッジャーノ", "ゆで汁"], "desc": "ゆでたてのパスタにバターとチーズを加え、ゆで汁でクリーミーにまとめる。ローマのレストランが広め、アメリカで「フェットチーネ・アルフレード」として有名になった。", "kind": "バターのソース", "tip": "ゆでたてのパスタに、室温に戻したバターとパルミジャーノを入れ、ゆで汁を加えながら手早く混ぜてクリーム状にする。"}, "tartufo": {"name": "白トリュフとバター", "en": "al Tartufo Bianco", "origin": "アルバ（ピエモンテ）", "color": "#F1E6CF", "ings": ["バター", "パルミジャーノ", "白トリュフ"], "desc": "バターで和えたパスタに、秋のアルバでとれる白トリュフを目の前で薄く削りかける。香りを味わう、贅沢な一皿。", "kind": "バターのソース", "tip": "トリュフは加熱すると香りが飛ぶので、バターで和えたパスタを皿に盛ってから、目の前で薄く削りかける。"}, "sugo_arrosto": {"name": "ローストの肉汁", "en": "Sugo d'Arrosto", "origin": "ピエモンテ", "color": "#7A4A2A", "ings": ["牛や豚のローストの焼き汁", "バター", "ローズマリー"], "desc": "肉をローストしたときの焼き汁を煮詰めたソース。詰め物の肉の味と重なり合う。", "kind": "肉の煮込み（ラグー）", "tip": "ローストの後、天板に残った焼き汁にワインかブロードを加えてこそげ落とし、バターを加えて煮詰める。"}, "valtellinese": {"name": "ヴァルテッリーナ風", "en": "alla Valtellinese", "origin": "ヴァルテッリーナ（ロンバルディア）", "color": "#F1E6CF", "ings": ["バター", "にんにく", "セージ", "カゼーラ（山のチーズ）", "ちりめんキャベツ", "じゃがいも"], "desc": "パスタと一緒にじゃがいもとキャベツをゆで、山のチーズと、にんにくとセージで香りをつけた溶かしバターを重ねる。アルプスの冬のごちそう。", "kind": "バターのソース", "tip": "パスタとじゃがいも、キャベツを同じ鍋でゆで、器にチーズと交互に重ねる。最後に、にんにくとセージで香りをつけた熱々の溶かしバターをかける。"}, "gorgonzola": {"name": "ゴルゴンゾーラ", "en": "al Gorgonzola", "origin": "ロンバルディア", "color": "#F1E6CF", "ings": ["ゴルゴンゾーラ", "生クリームまたは牛乳", "くるみ"], "desc": "ミラノ近郊生まれの青かびチーズを溶かした、濃厚でまろやかなソース。くるみを散らすと香ばしさが加わる。", "kind": "チーズ・卵・クリームのソース", "tip": "ゴルゴンゾーラは弱火で生クリームか牛乳に溶かす。辛口の「ピッカンテ」なら刺激的に、甘口の「ドルチェ」ならまろやかに仕上がる。"}, "salsa_veneta": {"name": "イン・サルサ（玉ねぎとアンチョビ）", "en": "Bigoli in Salsa", "origin": "ヴェネツィア（ヴェネト）", "color": "#7A4A2A", "ings": ["玉ねぎ", "アンチョビ（塩漬けのいわし）", "オリーブオイル"], "desc": "玉ねぎを弱火でじっくり煮て、アンチョビを溶かし込む。肉を食べない宗教上の日に食べられてきた、ヴェネツィアの素朴な味。", "kind": "魚介のソース", "tip": "玉ねぎは焦がさないよう、ごく弱火で30分ほど、とろりとするまで煮る。アンチョビは火を止める直前に加えて溶かす。"}, "anatra": {"name": "鴨のラグー", "en": "Ragù d'Anatra", "origin": "ヴェネト", "color": "#7A4A2A", "ings": ["鴨肉", "玉ねぎ・セロリ", "白ワイン", "ローズマリー"], "desc": "鴨を香味野菜とじっくり煮込んだラグー。ヴェネトでは、鴨でとったスープでパスタをゆでることもある。", "kind": "肉の煮込み（ラグー）", "tip": "鴨は皮目から焼いて余分な脂を出してから煮込む。脂はとっておくと、炒めものに使える。"}, "cinghiale": {"name": "イノシシのラグー", "en": "Ragù di Cinghiale", "origin": "トスカーナ", "color": "#7A4A2A", "ings": ["イノシシ肉", "赤ワイン", "トマト", "ローズマリー", "ジュニパーベリー"], "desc": "赤ワインに漬けて臭みを抜いたイノシシを、トマトとハーブでじっくり煮込む。山の多いトスカーナの冬の味。", "kind": "肉の煮込み（ラグー）", "tip": "イノシシ肉は赤ワインと香味野菜、ハーブにひと晩漬けてから煮込む。手に入らなければ豚肩肉で代用できる。"}, "aglione": {"name": "アリオーネ（大粒のにんにく）", "en": "all'Aglione", "origin": "ヴァル・ディキアーナ（トスカーナ）", "color": "#C2412D", "ings": ["大粒のにんにく「アリオーネ」", "トマト", "オリーブオイル", "唐辛子"], "desc": "キアーナ渓谷でとれる大粒で穏やかな香りのにんにくを、トマトと一緒にとろけるまで煮込む。", "kind": "トマトのソース", "tip": "にんにくを丸ごと弱火でゆっくり煮て、トマトに溶け込ませる。焦がさないのがいちばん大事。"}, "funghi": {"name": "ポルチーニ", "en": "ai Funghi Porcini", "origin": "トスカーナ、北イタリア", "color": "#7A4A2A", "ings": ["ポルチーニ茸", "にんにく", "イタリアンパセリ", "オリーブオイルまたはバター"], "desc": "秋の山でとれる香り高いポルチーニ茸のソース。乾燥ポルチーニを戻し汁ごと使えば、一年中作れる。", "kind": "オイルのソース", "tip": "ポルチーニは洗わずにふきんで汚れを落とす。乾燥なら、ぬるま湯で戻して戻し汁ごと使うと香りが濃くなる。"}, "brodo": {"name": "ブロード（スープ）", "en": "in Brodo", "origin": "エミリア・ロマーニャ", "color": "#E6C98E", "ings": ["去勢鶏（カッポーネ）や牛肉でとったスープ", "パルミジャーノ"], "desc": "詰め物パスタを澄んだ肉のスープに浮かべる。エミリア・ロマーニャのクリスマスの定番。", "kind": "スープ・豆と煮込む", "tip": "鶏や牛肉、香味野菜を水からごく弱火で数時間煮て、澄んだスープをとる。沸騰させると濁るので注意。"}, "panna": {"name": "パンナ（生クリーム）", "en": "alla Panna", "origin": "イタリア各地", "color": "#F1E6CF", "ings": ["生クリーム", "バター", "パルミジャーノ", "ナツメグ"], "desc": "生クリームとチーズのまろやかなソース。ボローニャの伝統派には邪道ともいわれるが、イタリア中で親しまれている。", "kind": "チーズ・卵・クリームのソース", "tip": "生クリームは沸騰させすぎると分離しやすい。弱火で軽く煮詰め、チーズを加えて濃度をつける。"}, "besciamella": {"name": "ベシャメル", "en": "Besciamella", "origin": "イタリア各地", "color": "#F1E6CF", "ings": ["バター", "小麦粉", "牛乳", "ナツメグ"], "desc": "バターで炒めた小麦粉を牛乳でのばす白いソース。ラザーニャやカネロニなど、オーブン料理でラグーと重ねる。", "kind": "チーズ・卵・クリームのソース", "tip": "溶かしたバターで小麦粉を焦がさないように炒め、温めた牛乳を少しずつ加えて泡立て器で混ぜるとダマにならない。"}, "ragu_salsiccia": {"name": "サルシッチャのラグー", "en": "Ragù di Salsiccia", "origin": "イタリア各地", "color": "#7A4A2A", "ings": ["サルシッチャ（生ソーセージ）", "玉ねぎ", "白ワイン", "トマト"], "desc": "生ソーセージの中身をほぐして炒め、ワインやトマトで煮込む。手早く作れるのに、肉の旨みがしっかり出る。", "kind": "肉の煮込み（ラグー）", "tip": "サルシッチャは皮を外し、木べらでほぐしながら焼き色がつくまで炒めてから、ワインを加える。"}, "ragu_agnello": {"name": "仔羊のラグー", "en": "Ragù d'Agnello", "origin": "アブルッツォ・モリーゼ", "color": "#C2412D", "ings": ["仔羊肉", "トマト", "にんにく", "ローズマリー", "唐辛子"], "desc": "羊飼いの文化が根づくアブルッツォの味。仔羊をトマトで煮込み、ペコリーノをかける。小さな肉団子「パロッテ」を入れることも。", "kind": "肉の煮込み（ラグー）", "tip": "仔羊肉は小さく切り、ローズマリーとにんにくで香りをつけて焼いてから、トマトで1時間ほど煮込む。"}, "piselli_prosciutto": {"name": "生ハムとグリーンピース", "en": "Prosciutto e Piselli", "origin": "エミリア・ロマーニャ", "color": "#5E8C3A", "ings": ["生ハム", "グリーンピース", "バター", "生クリーム"], "desc": "生ハムの塩気とグリーンピースの甘みを、バターや生クリームでまとめたやさしいソース。", "kind": "チーズ・卵・クリームのソース", "tip": "生ハムは細切りにして軽く炒め、グリーンピースを加えてから生クリームでまとめる。生ハムの塩気があるので塩は控えめに。"}, "salsa_noci": {"name": "くるみのソース", "en": "Salsa di Noci", "origin": "リグーリア", "color": "#F1E6CF", "ings": ["くるみ", "牛乳に浸したパン", "にんにく", "パルミジャーノ", "マジョラム"], "desc": "くるみをすりつぶして作る、まろやかでコクのあるリグーリアのソース。野草を詰めたパンソーティと合わせるのが定番。", "kind": "ペースト", "tip": "くるみは薄皮が気になるなら湯通しして取ると、色も味もまろやかに。パンを牛乳に浸してから、ほかの材料と一緒にすりつぶす。"}};
const PASTA_SAUCE_KINDS = ["トマトのソース", "オイルのソース", "チーズ・卵・クリームのソース", "バターのソース", "肉の煮込み（ラグー）", "魚介のソース", "ペースト", "スープ・豆と煮込む"];
/* パスタのイラスト（写真の代わり）：形ごとに描き分ける。viewBox 0 0 64 64 */
const PASTA_DOUGH = { durum:'#EBC874', egg:'#F2BC45', whole:'#C49A66', buck:'#8E745B', green:'#8FA858', potato:'#EDD6A0', toast:'#D29A50', pale:'#F0DAA2', saffron:'#F0AE2E' };
function pastaSVG(shape, dough){
  const F = PASTA_DOUGH[dough] || dough || PASTA_DOUGH.durum;
  const dk = (h, f) => { const n=parseInt(h.slice(1),16); const c=[n>>16,(n>>8)&255,n&255].map(v=>Math.round(v*(1-f))); return '#'+c.map(v=>v.toString(16).padStart(2,'0')).join(''); };
  const S = dk(F,.42), D = dk(F,.16), H = 'rgba(255,255,255,.55)';
  const r1 = n => Math.round(n*10)/10;
  let seed = 7; const rnd = () => (seed = (seed*9301+49297)%233280)/233280;
  // 輪郭つきの線（麺など）
  const line = (d, w) => `<path d="${d}" fill="none" stroke="${S}" stroke-width="${w+1.6}" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="${F}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
  const shape_ = (d, fill=F, w=1.3) => `<path d="${d}" fill="${fill}" stroke="${S}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"/>`;
  const thin = (d, o=.55, w=1) => `<path d="${d}" fill="none" stroke="${S}" stroke-width="${w}" stroke-linecap="round" opacity="${o}"/>`;
  const g = (t, inner) => `<g transform="${t}">${inner}</g>`;
  const ell = (cx,cy,rx,ry,fill=F,w=1.3) => `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${fill}" stroke="${S}" stroke-width="${w}"/>`;
  const out = [];
  // 束になった乾麺
  const bundle = (n, w, gap, hollow) => {
    for(let i=0;i<n;i++){ const o=(i-(n-1)/2)*gap, ox=o*.707, oy=o*.707, L=(i%2?1.5:0)+(i%3?0:2);
      out.push(line(`M${r1(12+ox+L)},${r1(52+oy-L)}L${r1(52+ox-L)},${r1(12+oy+L)}`, w)); }
    if(hollow) for(let i=0;i<n;i++){ const o=(i-(n-1)/2)*gap, ox=o*.707, oy=o*.707, L=(i%2?1.5:0)+(i%3?0:2);
      out.push(`<circle cx="${r1(52+ox-L)}" cy="${r1(12+oy+L)}" r="${r1(w/2+.6)}" fill="${F}" stroke="${S}" stroke-width="1"/><circle cx="${r1(52+ox-L)}" cy="${r1(12+oy+L)}" r="${r1(w/5)}" fill="${S}"/>`); }
    out.push(g('rotate(-45 32 32)', `<rect x="28.5" y="${r1(32-n*gap/2-2)}" width="7" height="${r1(n*gap+4)}" rx="1.5" fill="#B5473A" stroke="${dk('#B5473A',.35)}" stroke-width="1"/>`));
  };
  // 渦を巻いた卵麺の巣
  const nest = (w, k, step, rot=9) => {
    for(let i=0;i<k;i++){ const rx=21-i*step, ry=15-i*step*.72; if(rx<3) break;
      out.push(`<ellipse cx="32" cy="34" rx="${r1(rx)}" ry="${r1(ry)}" transform="rotate(${-14+i*rot} 32 34)" fill="none" stroke="${S}" stroke-width="${w+1.6}"/>`,
               `<ellipse cx="32" cy="34" rx="${r1(rx)}" ry="${r1(ry)}" transform="rotate(${-14+i*rot} 32 34)" fill="none" stroke="${i%2?D:F}" stroke-width="${w}"/>`); }
  };
  const wavy = (y, amp, ph, w, x0=8, x1=56, tilt=0) => { let d=''; for(let x=x0;x<=x1;x+=2){ const yy=y+amp*Math.sin(x/5+ph)+(x-32)*tilt; d+=(d?'L':'M')+r1(x)+','+r1(yy); } out.push(line(d,w)); };
  switch(shape){
    case 'long': bundle(7, 2.2, 3.2); break;
    case 'flat_long': bundle(6, 3.2, 3.8); break;
    case 'square_long': bundle(7, 2.4, 3.1); out.push(thin('M20,44L44,20',.25)); break;
    case 'hollow_long': bundle(5, 3.6, 4.6, true); break;
    case 'thick_long': [16,23,30,37,44,51].forEach((y,i)=>wavy(y, 2, i*1.3, 4.2, 8, 56, -.12)); break;
    case 'nest': nest(3.2, 6, 3.4); break;
    case 'nest_thin': nest(1.9, 9, 2.2, 7); break;
    case 'wide_nest': nest(6.2, 3, 6.2, 16); break;
    case 'buck_strips': for(let i=0;i<9;i++){ const x=12+rnd()*36, y=14+rnd()*34, a=-50+rnd()*100;
        out.push(g(`rotate(${r1(a)} ${r1(x)} ${r1(y)})`, shape_(`M${r1(x-9)},${r1(y-2.6)}h18v5.2h-18z`, i%2?D:F))); } break;
    case 'tria': nest(3, 5, 3.6); [[20,22],[44,26],[40,46],[24,46],[32,30]].forEach(([x,y],i)=>out.push(`<circle cx="${x}" cy="${y}" r="4" fill="#E2C48E" stroke="#9C7A45" stroke-width="1.2"/>`,thin(`M${x-1.5},${y-2}q1.5,2 0,4`,.6)));
      out.push(line('M14,38q6,-6 12,0', 3).replace(new RegExp(F,'g'), dk(F,.3))); break;
    case 'flat_thick': for(let i=0;i<6;i++){ const y=14+i*7.4, ph=i*1.7; let d=''; for(let x=12;x<=50;x+=2){ d+=(d?'L':'M')+r1(x+(i%2?2:-2))+','+r1(y+2.4*Math.sin(x/6+ph)); } out.push(line(d, 5)); } break;
    case 'ziti': [[18,0],[30,6],[42,-4]].forEach(([y,dx])=>out.push(g('rotate(-30 32 32)',
        `<rect x="${8+dx}" y="${y}" width="44" height="8" fill="${F}" stroke="${S}" stroke-width="1.3"/>`+ell(52+dx,y+4,2.2,4)+`<ellipse cx="${52+dx}" cy="${y+4}" rx="1" ry="2.3" fill="${S}" opacity=".7"/>`+thin(`M${10+dx},${y+2}H${50+dx}`,.3)))); break;
    case 'penne': case 'garganelli': {
      const one = (t, egg) => g(t, shape_('M-14,-5.5L10,-5.5L16,5.5L-8,5.5Z') + `<ellipse cx="13" cy="0" rx="6.3" ry="2.7" transform="rotate(61 13 0)" fill="${F}" stroke="${S}" stroke-width="1.3"/><ellipse cx="13" cy="0" rx="4.4" ry="1.5" transform="rotate(61 13 0)" fill="${S}" opacity=".7"/>` +
        (egg ? [-9,-5,-1,3,7].map(x=>thin(`M${x},-4.4l${4.8},9`,.5)).join('') + thin('M-13,-3H11',.4) : [-3,0,3].map(y=>thin(`M${-13+(y+5)*.6},${y}H${11+(y+5)*.6}`,.5)).join('')));
      [[`translate(26 22) rotate(-24) scale(1.15)`],[`translate(38 40) rotate(18) scale(1.15)`],[`translate(22 48) rotate(-60) scale(.95)`]].forEach(([t])=>out.push(one(t, shape==='garganelli'))); break; }
    case 'rigatoni': {
      const one = t => g(t, `<rect x="-13" y="-6" width="24" height="12" fill="${F}" stroke="${S}" stroke-width="1.3"/>` + [-3,0,3].map(y=>thin(`M-12,${y}H10`,.5)).join('') + ell(11,0,3.4,6) + `<ellipse cx="11" cy="0" rx="1.8" ry="3.8" fill="${S}" opacity=".75"/>`);
      out.push(one('translate(28 22) rotate(-20)'), one('translate(38 40) rotate(25)'), one('translate(20 46) rotate(-70) scale(.9)')); break; }
    case 'pacchero': case 'ditali': {
      const one = (x,y,s) => g(`translate(${x} ${y}) scale(${s})`, `<path d="M-9,0V16a9,3.6 0 0 0 18,0V0" fill="${F}" stroke="${S}" stroke-width="1.3"/>` + ell(0,0,9,3.6) + `<ellipse cx="0" cy="0.4" rx="6.6" ry="2.4" fill="${S}" opacity=".7"/>` +
        (shape==='ditali' ? [-5,0,5].map(x=>thin(`M${x},4V${17.5-Math.abs(x)*.2}`,.45)).join('') : thin('M-5,4V18',.25)));
      (shape==='pacchero' ? [[22,20,1.25],[42,26,1.25],[30,38,1.25]] : [[16,16,.85],[34,14,.85],[50,20,.85],[22,34,.85],[42,36,.85],[30,50,.85]]).forEach(a=>out.push(one(...a))); break; }
    case 'spiral': {
      const one = t => { let s=''; for(let i=0;i<7;i++){ s+=`<ellipse cx="${-15+i*5}" cy="0" rx="3.6" ry="6.4" transform="rotate(28 ${-15+i*5} 0)" fill="${i%2?D:F}" stroke="${S}" stroke-width="1.2"/>`; } return g(t, s); };
      out.push(one('translate(30 20) rotate(-15)'), one('translate(34 42) rotate(20)')); break; }
    case 'corkscrew': { const one = (y, t) => { let s=''; for(let i=0;i<9;i++){ const x=-20+i*5; s+=`<ellipse cx="${x}" cy="0" rx="3.4" ry="8" fill="none" stroke="${S}" stroke-width="4.4"/><ellipse cx="${x}" cy="0" rx="3.4" ry="8" fill="none" stroke="${i%2?D:F}" stroke-width="2.8"/>`; } return g(t, s); };
      out.push(one(0,'translate(32 21) rotate(-12)'), one(0,'translate(32 44) rotate(8)')); break; }
    case 'ear': [[20,20],[42,18],[31,33],[18,46],[44,44]].forEach(([x,y],i)=>out.push(ell(x,y,10,8.5), `<ellipse cx="${x+.6}" cy="${y+.8}" rx="6.2" ry="5" fill="${D}" stroke="${S}" stroke-width=".8" opacity=".9"/>`, thin(`M${x-6},${y-4.5}q6,-3 12,0`,.5,1.1))); break;
    case 'cavatelli': case 'gnocchetti': [[20,18,-20],[42,16,25],[28,32,10],[48,34,-30],[16,44,40],[36,48,-10]].forEach(([x,y,a])=>out.push(g(`translate(${x} ${y}) rotate(${a})`,
        ell(0,0,8.5,4.6) + (shape==='cavatelli' ? `<path d="M-6,0q6,-3 12,0q-6,3 -12,0z" fill="${S}" opacity=".55"/>` : [-5,-2.5,0,2.5,5].map(x=>thin(`M${x},-4q-1.2,4 0,8`,.6)).join('') + `<path d="M-7,0q7,-2.4 14,0" fill="none" stroke="${S}" stroke-width="1" opacity=".5"/>`)))); break;
    case 'twist': [[18,18,-30],[38,16,20],[50,30,70],[28,30,-5],[16,42,50],[36,44,-40],[48,50,10]].forEach(([x,y,a])=>out.push(g(`translate(${x} ${y}) rotate(${a})`,
        shape_('M-9,0q4,-3.4 9,-3.4t9,3.4q-4,3.4 -9,3.4t-9,-3.4z') + [-5,-1.5,2,5.5].map(x=>thin(`M${x-1.5},-3l3,6`,.55)).join('')))); break;
    case 'twist_long': [[30,16,-15],[28,32,10],[32,48,-8]].forEach(([x,y,a])=>out.push(g(`translate(${x} ${y}) rotate(${a})`,
        shape_('M-18,0q2,-4 10,-4h16q10,0 10,4q-2,4 -10,4h-16q-8,0 -10,-4z') + [-12,-7,-2,3,8,13].map(x=>thin(`M${x-2},-3.6l4,7.2`,.55)).join('')))); break;
    case 'scroll': [[30,16,-10],[24,30,12],[36,42,-6],[26,54,4]].forEach(([x,y,a])=>out.push(g(`translate(${x} ${y}) rotate(${a})`,
        shape_('M-13,-3h26q3,0 3,3t-3,3h-26q-3,0 -3,-3t3,-3z') + thin('M-12,0H12',.6,1.2) + thin('M-13,-3q-2,3 0,6',.5) + thin('M13,-3q2,3 0,6',.5)))); break;
    case 'rings': [[16,16],[28,14],[40,16],[52,20],[20,28],[33,27],[46,31],[14,40],[27,40],[40,43],[52,44],[22,52],[35,54],[47,55]].forEach(([x,y],i)=>out.push(`<circle cx="${x}" cy="${y}" r="4.3" fill="none" stroke="${S}" stroke-width="3.6"/><circle cx="${x}" cy="${y}" r="4.3" fill="none" stroke="${i%3?F:D}" stroke-width="2.2"/>`)); break;
    case 'beads': for(let i=0;i<70;i++){ const a=rnd()*Math.PI*2, rr=Math.sqrt(rnd())*21, x=32+rr*Math.cos(a), y=36+rr*Math.sin(a)*.72, c=[F,D,dk(F,.3),F][Math.floor(rnd()*4)];
        out.push(`<circle cx="${r1(x)}" cy="${r1(y)}" r="${r1(1.5+rnd()*1.2)}" fill="${c}" stroke="${S}" stroke-width=".6"/>`); } break;
    case 'square': case 'square_big': {
      const z = shape==='square_big' ? 12 : 10;
      const one = (x,y,a) => { let d=''; const n=8, st=2*z/n; for(let i=0;i<n;i++) d+=`L${r1(-z+i*st+st/2)},${-z-1.4}L${r1(-z+(i+1)*st)},${-z}`; for(let i=0;i<n;i++) d+=`L${z+1.4},${r1(-z+i*st+st/2)}L${z},${r1(-z+(i+1)*st)}`;
        for(let i=0;i<n;i++) d+=`L${r1(z-i*st-st/2)},${z+1.4}L${r1(z-(i+1)*st)},${z}`; for(let i=0;i<n;i++) d+=`L${-z-1.4},${r1(z-i*st-st/2)}L${-z},${r1(z-(i+1)*st)}`;
        return g(`translate(${x} ${y}) rotate(${a})`, shape_('M'+(-z)+','+(-z)+d.slice(1)+'Z') + `<rect x="${-z*.62}" y="${-z*.62}" width="${z*1.24}" height="${z*1.24}" rx="${z*.5}" fill="${D}" opacity=".85"/>` + thin(`M${-z*.4},${-z*.3}q${z*.4},${-z*.25} ${z*.8},0`,.35)); };
      (shape==='square_big' ? [[22,22,-8],[44,40,10]] : [[20,20,-6],[44,22,8],[30,44,-14]]).forEach(a=>out.push(one(...a))); break; }
    case 'plin': [[18,18,-10],[40,16,8],[28,32,-4],[48,34,15],[16,46,6],[38,50,-12]].forEach(([x,y,a])=>out.push(g(`translate(${x} ${y}) rotate(${a})`,
        shape_('M-9,-3q-2,-4 3,-4q3,0 6,3q3,-3 6,-3q5,0 3,4v6q2,4 -3,4q-3,0 -6,-3q-3,3 -6,3q-5,0 -3,-4z') + thin('M0,-4V4',.7,1.2) + `<ellipse cx="-4.5" cy="0" rx="3" ry="2.6" fill="${D}" opacity=".8"/><ellipse cx="4.5" cy="0" rx="3" ry="2.6" fill="${D}" opacity=".8"/>`))); break;
    case 'ring': case 'hat': [[21,21,-20],[43,23,30],[30,44,0]].forEach(([x,y,a])=>out.push(g(`translate(${x} ${y}) rotate(${a})`,
        shape_('M-11,2q0,-11 11,-11q11,0 11,11q-3,6 -11,6q-8,0 -11,-6z') + (shape==='ring' ? `<circle cx="0" cy="1" r="3" fill="${S}" opacity=".75"/>` + shape_('M-11,2q4,8 11,8q7,0 11,-8q-4,3 -11,3q-7,0 -11,-3z', D, 1)
          : `<ellipse cx="0" cy="-2.5" rx="5.5" ry="5" fill="${D}" stroke="${S}" stroke-width="1"/>` + shape_('M-13,4q2,-3 6,-3h14q4,0 6,3q-6,4 -13,4q-7,0 -13,-4z', F, 1.1)) + thin('M-6,-6q6,-3 12,0',.4)))); break;
    case 'triangle': [[22,24,0],[44,38,180],[24,48,20]].forEach(([x,y,a])=>{ let d='M0,-13'; const pts=[[0,-13],[12,9],[-12,9],[0,-13]];
        for(let s=0;s<3;s++){ const [x0,y0]=pts[s],[x1,y1]=pts[s+1]; for(let i=1;i<=6;i++){ const t=i/6, mx=x0+(x1-x0)*(t-1/12), my=y0+(y1-y0)*(t-1/12), nx=-(y1-y0)/24, ny=(x1-x0)/24; d+=`L${r1(mx-nx*1.4)},${r1(my-ny*1.4)}L${r1(x0+(x1-x0)*t)},${r1(y0+(y1-y0)*t)}`; } }
        out.push(g(`translate(${x} ${y}) rotate(${a})`, shape_(d+'Z') + `<path d="M0,-6L6,5H-6Z" fill="${D}" stroke="${D}" stroke-width="5" stroke-linejoin="round" opacity=".85"/>`)); }); break;
    case 'wheat': [[22,20,-25],[42,30,20],[24,46,-5]].forEach(([x,y,a])=>out.push(g(`translate(${x} ${y}) rotate(${a})`,
        shape_('M-14,0q4,-9 14,-9q10,0 14,9q-4,9 -14,9q-10,0 -14,-9z') + thin('M-12,0H12',.6,1.1) + [-9,-5,-1,3,7].map(x=>thin(`M${x},0l3,-5M${x},0l3,5`,.6,1.1)).join('')))); break;
    case 'sheet': [[0,0],[4,10],[8,20]].forEach(([dx,dy],i)=>{ let top='', bot=''; for(let x=0;x<=40;x+=2){ top+=`L${r1(10+dx+x)},${r1(14+dy+1.4*Math.sin(x/2))}`; bot=`L${r1(10+dx+x)},${r1(28+dy+1.4*Math.sin(x/2))}`+bot; }
        out.push(shape_('M'+top.slice(1)+bot+'Z', i%2?D:F)); }); out.push(`<path d="M18,52h30" stroke="#B5473A" stroke-width="3" stroke-linecap="round" opacity=".55"/>`); break;
    case 'gnocchi': [[20,18,-15],[42,18,10],[30,32,20],[16,44,-5],[42,44,-25],[30,54,5]].forEach(([x,y,a])=>out.push(g(`translate(${x} ${y}) rotate(${a})`,
        shape_('M-8,-5q8,-3 16,0q3,5 0,10q-8,3 -16,0q-3,-5 0,-10z') + [-4,0,4].map(x=>thin(`M${x},-4.6q1.4,4.6 0,9.2`,.55,1.1)).join('')))); break;
    case 'disc': out.push(`<rect x="6" y="20" width="52" height="34" rx="6" fill="#E8E2D6" stroke="#A39A88" stroke-width="1.3"/>`);
      [[18,30],[32,30],[46,30],[18,44],[32,44],[46,44]].forEach(([x,y])=>out.push(ell(x,y,7.5,6.2), `<ellipse cx="${x+1}" cy="${y-1}" rx="4" ry="3" fill="${dk(F,.3)}" opacity=".55"/>`)); break;
    default: out.push(ell(32,32,14,10));
  }
  return `<svg viewBox="0 0 64 64" aria-hidden="true">${out.join('')}</svg>`;
}
/* パスタソースのイラスト：皿に盛ったソースと、分類ごとの飾り */
function sauceSVG(s){
  const C = s.color || '#C2412D';
  const dk = (h, f) => { const n=parseInt(h.slice(1),16); const c=[n>>16,(n>>8)&255,n&255].map(v=>Math.round(v*(1-f))); return '#'+c.map(v=>v.toString(16).padStart(2,'0')).join(''); };
  const lt = (h, f) => { const n=parseInt(h.slice(1),16); const c=[n>>16,(n>>8)&255,n&255].map(v=>Math.round(v+(255-v)*f)); return '#'+c.map(v=>v.toString(16).padStart(2,'0')).join(''); };
  const leaf = (x,y,a,c='#4E8A32') => `<path transform="translate(${x} ${y}) rotate(${a})" d="M0,-6q5,3 0,12q-5,-9 0,-12z" fill="${c}" stroke="${dk(c,.35)}" stroke-width=".8"/><path transform="translate(${x} ${y}) rotate(${a})" d="M0,-5V5" stroke="${dk(c,.4)}" stroke-width=".6"/>`;
  const dots = (pts, r, c, sc) => pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"${sc?` stroke="${sc}" stroke-width=".7"`:''}/>`).join('');
  const k = s.kind || '';
  let top = '';
  if(/トマト/.test(k)) top = leaf(26,30,-30) + leaf(36,28,40) + dots([[42,36],[22,38]],1.6,'#F2E2B0');
  else if(/オイル/.test(k)) top = [[24,32],[38,30],[31,38]].map(([x,y])=>`<ellipse cx="${x}" cy="${y}" rx="3.4" ry="2.4" fill="#F4E7C2" stroke="#C9A85E" stroke-width=".8"/><circle cx="${x}" cy="${y}" r=".8" fill="#C9A85E"/>`).join('') + `<path d="M40,38l6,-6" stroke="#C2302A" stroke-width="2.4" stroke-linecap="round"/><path d="M20,28l5,-4" stroke="#C2302A" stroke-width="2.2" stroke-linecap="round"/>` + leaf(30,26,80,'#5E8C3A');
  else if(/チーズ|クリーム/.test(k)) top = dots([[24,31],[29,35],[35,30],[40,35],[31,28],[27,38],[38,39],[44,31],[20,35]],.9,'#2A2420') + `<path d="M26,33q6,-3 12,0" stroke="#fff" stroke-width="1.2" fill="none" opacity=".6"/>`;
  else if(/バター/.test(k)) top = leaf(26,31,-50,'#7D9A6A') + leaf(37,32,30,'#7D9A6A') + `<rect x="29" y="25" width="7" height="5" rx="1" fill="#F7E08A" stroke="#C9A94A" stroke-width=".8"/>`;
  else if(/ラグー/.test(k)) top = dots([[24,31],[30,29],[36,31],[42,34],[27,37],[34,36],[39,39],[22,35]],1.9,dk(C,.25),dk(C,.5)) + leaf(33,26,10,'#5E8C3A');
  else if(/魚介/.test(k)) top = [[25,32,-20],[39,33,25]].map(([x,y,a])=>`<path transform="translate(${x} ${y}) rotate(${a})" d="M-6,1q6,-10 12,0q-6,4 -12,0z" fill="#E9DCC6" stroke="#8C7A62" stroke-width=".9"/><path transform="translate(${x} ${y}) rotate(${a})" d="M-3,0l3,-5l3,5" fill="none" stroke="#8C7A62" stroke-width=".6"/>`).join('') + `<path d="M28,38q4,-6 9,-2q-3,4 -9,2z" fill="#F08A5A" stroke="#B85A30" stroke-width=".8"/>` + leaf(33,27,0,'#5E8C3A');
  else if(/ペースト/.test(k)) top = dots([[26,31],[35,29],[40,35],[30,37]],2,'#F3E3B8','#C9A85E') + leaf(32,33,60);
  else top = dots([[24,32],[31,30],[38,33],[28,37],[36,38],[42,30]],2.4,'#D9C08E','#9C7A45') + leaf(33,26,20,'#5E8C3A');
  return `<svg viewBox="4 12 56 50" aria-hidden="true"><ellipse cx="32" cy="36" rx="27" ry="17" fill="#FBF8F2" stroke="#B9AE9A" stroke-width="1.3"/><ellipse cx="32" cy="35" rx="19" ry="11" fill="#EFE8DA" stroke="#D8CDB8" stroke-width=".8"/>`+
    `<path d="M15,34q3,-9 17,-10q15,1 17,10q-2,8 -17,9q-15,-1 -17,-9z" fill="${C}" stroke="${dk(C,.3)}" stroke-width="1"/><path d="M20,30q8,-5 18,-3" stroke="${lt(C,.45)}" stroke-width="1.6" fill="none" stroke-linecap="round" opacity=".7"/>${top}</svg>`;
}

